BEGIN;
CREATE TABLE publisher_memberships (id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publishers(id),user_id TEXT NOT NULL REFERENCES users(id),app_role TEXT NOT NULL CHECK(app_role IN ('PUBLISHER_MEMBER','PUBLISHER_ADMIN','REVIEWER')),status TEXT NOT NULL DEFAULT 'ACTIVE',UNIQUE(publisher_id,user_id));
CREATE TABLE commercial_candidates (id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publishers(id),product_version_id TEXT NOT NULL REFERENCES product_versions(id),state TEXT NOT NULL CHECK(state IN ('NEW','NEEDS_EVALUATION','NEEDS_RUNTIME_BUILD','NEEDS_OFFER','READY_FOR_REVIEW','BLOCKED','PUBLISHED')),blockers JSONB NOT NULL DEFAULT '[]'::jsonb,evidence JSONB NOT NULL DEFAULT '{}'::jsonb,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(publisher_id,product_version_id));
CREATE TABLE canon_change_proposals (id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publishers(id),canonical_ref TEXT NOT NULL,proposed_patch JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN ('DRAFT','SUBMITTED','ACCEPTED_UPSTREAM','REJECTED_UPSTREAM','WITHDRAWN')),created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE publication_reviews (id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publishers(id),product_version_id TEXT NOT NULL REFERENCES product_versions(id),expected_version_hash TEXT NOT NULL,packet JSONB NOT NULL,status TEXT NOT NULL CHECK(status IN ('PENDING','APPROVED','REJECTED','STALE')),reviewer_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),decided_at TIMESTAMPTZ);
CREATE TABLE runtime_build_jobs (id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publishers(id),product_version_id TEXT NOT NULL REFERENCES product_versions(id),runtime TEXT NOT NULL,adapter_version TEXT NOT NULL DEFAULT '',state TEXT NOT NULL CHECK(state IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','UNAVAILABLE')),artifact_hash TEXT,UNIQUE(product_version_id,runtime,adapter_version));
CREATE TABLE publisher_audit_events (id TEXT PRIMARY KEY,publisher_id TEXT NOT NULL REFERENCES publishers(id),actor_id TEXT NOT NULL,object_ref TEXT NOT NULL,action TEXT NOT NULL,before_hash TEXT,after_hash TEXT,result TEXT NOT NULL,correlation_id TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
COMMIT;
